function check(input, actual, expected) {
  const [pairs] = input;
  if (!Array.isArray(actual) || actual.length !== pairs.length) return false;
  const key = (pair) => pair[0] + ',' + pair[1];
  const remaining = new Map();
  for (const pair of pairs) remaining.set(key(pair), (remaining.get(key(pair)) ?? 0) + 1);
  for (let i = 0; i < actual.length; i++) {
    const pair = actual[i];
    if (!Array.isArray(pair) || pair.length !== 2 || typeof pair[0] !== 'number' || typeof pair[1] !== 'number') return false;
    const count = remaining.get(key(pair));
    if (!count) return false;
    remaining.set(key(pair), count - 1);
    if (i > 0 && actual[i - 1][1] !== pair[0]) return false;
  }
  return true;
}

