function validate([pairs]) {
  if (!Array.isArray(pairs) || pairs.length < 1 || pairs.length > 100000) return 'pairs needs 1 to 100,000 entries.';
  const seen = new Set();
  const parent = new Map();
  const find = (x) => {
    while (parent.get(x) !== x) {
      parent.set(x, parent.get(parent.get(x)));
      x = parent.get(x);
    }
    return x;
  };
  const balance = new Map();
  for (const pair of pairs) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each pair has exactly two numbers.';
    const [from, to] = pair;
    if (![from, to].every(v => Number.isInteger(v) && v >= 0 && v <= 1e9)) return 'Each number is a whole number from 0 to 10^9.';
    if (from === to) return 'A pair cannot start and end at the same number.';
    if (seen.has(from + ',' + to)) return 'No two pairs may be identical.';
    seen.add(from + ',' + to);
    for (const v of [from, to]) if (!parent.has(v)) parent.set(v, v);
    parent.set(find(from), find(to));
    balance.set(from, (balance.get(from) ?? 0) + 1);
    balance.set(to, (balance.get(to) ?? 0) - 1);
  }
  const roots = new Set([...parent.keys()].map(find));
  const extra = [...balance.values()].filter(d => d !== 0);
  const chains = roots.size === 1 && (extra.length === 0 || (extra.length === 2 && extra.includes(1) && extra.includes(-1)));
  return chains ? null : 'These pairs cannot be chained into one valid arrangement.';
}

