function validArrangement(pairs) {
  // Backtracking: try every unused pair that links onto the chain built so far.
  const used = new Array(pairs.length).fill(false);
  const order = [];
  const extend = () => {
    if (order.length === pairs.length) return true;
    for (let i = 0; i < pairs.length; i++) {
      if (used[i]) continue;
      if (order.length > 0 && order[order.length - 1][1] !== pairs[i][0]) continue;
      used[i] = true;
      order.push(pairs[i]);
      if (extend()) return true;
      used[i] = false;
      order.pop();
    }
    return false;
  };
  extend();
  return order.map(pair => [pair[0], pair[1]]);
}

