function generate(rand, size) {
  const large = size === 'large';
  const nodes = large ? 60 : 2 + Math.floor(rand() * 4);
  const steps = large ? 2000 : 1 + Math.floor(rand() * 7);
  // Random distinct labels for the nodes.
  const labels = [];
  const taken = new Set();
  while (labels.length < nodes) {
    const value = large ? Math.floor(rand() * 1000000001) : Math.floor(rand() * 10);
    if (!taken.has(value)) { taken.add(value); labels.push(value); }
  }
  // A random walk that never repeats a pair is itself a valid arrangement.
  const used = new Set();
  let current = Math.floor(rand() * nodes);
  const walk = [];
  while (walk.length < steps) {
    const options = [];
    for (let next = 0; next < nodes; next++) if (next !== current && !used.has(current * nodes + next)) options.push(next);
    if (!options.length) break;
    const next = options[Math.floor(rand() * options.length)];
    used.add(current * nodes + next);
    walk.push([labels[current], labels[next]]);
    current = next;
  }
  // Shuffle so the walk order is hidden.
  for (let i = walk.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [walk[i], walk[j]] = [walk[j], walk[i]];
  }
  return [walk];
}
